function g({registerIndicator:b,sourceValues:y,nulls:N}){b({id:"oa-cti",name:"Correlation Trend Indicator (CTI)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:20,min:2,max:5e3,step:1}],plots:[{key:"cti",type:"line",title:"CTI",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:.5,title:"Upper",color:"#787b86",dashed:!0},{price:0,title:"Zero",color:"#787b86",dashed:!0},{price:-.5,title:"Lower",color:"#787b86",dashed:!0}],range:()=>({min:-1.05,max:1.05}),calc(s,p){const a=Math.min(5e3,Math.max(2,Math.floor(Number(p.period)||20))),M=y(s,p.source??"close"),u=new Array(s.length).fill(NaN),f=new Array(a).fill(NaN);let l=0,i=0,o=0,d=0,r=0;for(let n=0;n<s.length;n++){const t=M[n];if(!Number.isFinite(t))continue;const c=f[i];if(Number.isFinite(c)?(o-=c,d-=c*c,r-=o,r+=(a-1)*t):(r+=l*t,l+=1),o+=t,d+=t*t,f[i]=t,i=(i+1)%a,l<2)continue;const e=l,m=e*(e-1)/2,x=e*(e-1)*(2*e-1)/6,C=e*x-m*m,X=e*d-o*o,h=C*X;if(h<=0){u[n]=0;continue}const Y=(e*r-m*o)/Math.sqrt(h);u[n]=Math.max(-1,Math.min(1,Y))}return{cti:N(u)}}})}export{g as default};
